const DISTRICT_GEOJSON: GeoJSON.Feature<GeoJSON.Polygon> = {
  type: "Feature",
  geometry: { type: "Polygon", coordinates: [DISTRICT_COORDS] },
  properties: { name: "Nərimanov rayonu" },
};

// Outside-district mask: world bbox with the district cut as a hole
const OUTSIDE_MASK: GeoJSON.Feature<GeoJSON.Polygon> = {
  type: "Feature",
  geometry: {
    type: "Polygon",
    coordinates: [
      [[-180, -85], [180, -85], [180, 85], [-180, 85], [-180, -85]],
      DISTRICT_COORDS,
    ],
  },
  properties: {},
};

const district = turf.polygon([DISTRICT_COORDS]);
const districtBbox = turf.bbox(district);
const districtCentroid = turf.centroid(district);
const districtSearch = turf.buffer(district, 0.3, { units: "kilometers" })!;

const PRIORITY_COLORS: Record<string, string> = {
  low: "#22c55e", medium: "#3b82f6", high: "#f97316", critical: "#ef4444",
};
const PRIORITY_LABELS: Record<string, string> = {
  low: "Aşağı", medium: "Orta", high: "Yüksək", critical: "Kritik",
};
const STATUS_LABELS: Record<string, string> = {
  open: "Açıq", in_progress: "İcrada", resolved: "Həll edilib", closed: "Bağlı",
};

function buildComplaintsGeoJSON(complaints: Complaint[]): GeoJSON.FeatureCollection {
  return {
    type: "FeatureCollection",
    features: complaints
      .filter((c) => c.lat != null && c.lng != null)
      .map((c) => ({
        type: "Feature",
        geometry: { type: "Point", coordinates: [c.lng!, c.lat!] },
        properties: { id: c.id, title: c.title, priority: c.priority, status: c.status },
      })),
  };
}

function buildMonitoringGeoJSON(points: MonitoringPoint[]): GeoJSON.FeatureCollection {
  return {
    type: "FeatureCollection",
    features: points.map((p) => ({
      type: "Feature",
      geometry: { type: "Point", coordinates: [p.lng, p.lat] },
      properties: { id: p.id, type: p.type, label: p.label, statusText: p.statusText },
    })),
  };
}

interface SearchResult {
  id: string;
  name: string;
  address: string;
  lon: number;
  lat: number;
}

interface NarimanovMapProps {
  complaints?: Complaint[];
  monitoringPoints?: MonitoringPoint[];
  onLocationSelect?: (lat: number, lng: number) => void;
  selectedLocation?: { lat: number; lng: number } | null;
  hideBuiltinUI?: boolean;
  mapStyle?: string | object;
  initialBearing?: number;
  onMapReady?: (map: mapboxgl.Map) => void;
  onBuildingClick?: (featureId: string, lat: number, lng: number) => void;
}

export default function NarimanovMap({
  complaints = [],
  monitoringPoints = [],
  onLocationSelect,
  selectedLocation,
  hideBuiltinUI = false,
  mapStyle: mapStyleProp,
  initialBearing = 0,
  onMapReady,
  onBuildingClick,
}: NarimanovMapProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<mapboxgl.Map | null>(null);
  const selectedBuildingIdRef = useRef<string | number | null>(null);
  const onBuildingClickRef = useRef(onBuildingClick);
  onBuildingClickRef.current = onBuildingClick;
  const searchMarkerRef = useRef<mapboxgl.Marker | null>(null);
  const searchPopupRef = useRef<mapboxgl.Popup | null>(null);
  const selectedMarkerRef = useRef<mapboxgl.Marker | null>(null);
  const complaintsPopupRef = useRef<mapboxgl.Popup | null>(null);
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const onLocationSelectRef = useRef(onLocationSelect);
  const complaintsRef = useRef(complaints);
  const monitoringPointsRef = useRef(monitoringPoints);

  onLocationSelectRef.current = onLocationSelect;
  complaintsRef.current = complaints;
  monitoringPointsRef.current = monitoringPoints;

  const [districtOnly, setDistrictOnly] = useState(false);
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [noResults, setNoResults] = useState(false);

  // ── Map init ─────────────────────────────────────────────────────────────
  useEffect(() => {
    if (!containerRef.current || !MAPBOX_TOKEN) return;

    mapboxgl.accessToken = MAPBOX_TOKEN;

    const map = new mapboxgl.Map({
      container: containerRef.current,
      style: mapStyleProp ?? MAPBOX_STYLE,
      center: [49.87, 40.409],
      zoom: 14,
      pitch: 45,
      bearing: initialBearing,
      attributionControl: false,
    });

    mapRef.current = map;

    map.addControl(new mapboxgl.NavigationControl(), "top-right");

    map.on("load", () => {
      // 3D buildings — skip if the custom style already defines this layer
      if (!map.getLayer("3d-buildings")) {
        try {
          map.addLayer({
            id: "3d-buildings",
            source: "composite",
            "source-layer": "building",
            filter: ["==", "extrude", "true"],
            type: "fill-extrusion",
            minzoom: 12,
            paint: {
              "fill-extrusion-color": "#c8d1dc",
              "fill-extrusion-height": ["get", "height"],
              "fill-extrusion-base": ["get", "min_height"],
              "fill-extrusion-opacity": [
                "interpolate", ["linear"], ["zoom"],
                12, 0.15, 13, 0.45, 14, 0.65,
              ],
            },
          });
        } catch {}
      }

      // Outside-district shade
      map.addSource("district-mask", { type: "geojson", data: OUTSIDE_MASK });
      map.addLayer({
        id: "district-shade",
        type: "fill",
        source: "district-mask",
        paint: { "fill-color": "rgba(0,0,0,0.45)" },
      });

      // District boundary line
      map.addSource("district-border", { type: "geojson", data: DISTRICT_GEOJSON });
      map.addLayer({
        id: "district-line",
        type: "line",
        source: "district-border",
        paint: { "line-color": "#0078FF", "line-width": 2.5 },
      });

      // Complaint markers (colored circles by priority)
      map.addSource("complaints", {
        type: "geojson",
        data: buildComplaintsGeoJSON(complaintsRef.current),
      });
      map.addLayer({
        id: "complaint-circles",
        type: "circle",
        source: "complaints",
        paint: {
          "circle-radius": ["match", ["get", "priority"],
            "critical", 13, "high", 11, "medium", 9, "low", 8, 9],
          "circle-color": ["match", ["get", "priority"],
            "critical", "#ef4444", "high", "#f97316",
            "medium", "#3b82f6", "low", "#22c55e", "#6b7280"],
          "circle-stroke-width": 2.5,
          "circle-stroke-color": "#ffffff",
          "circle-opacity": 0.92,
        },
      });

      // Monitoring markers
      map.addSource("monitoring", {
        type: "geojson",
        data: buildMonitoringGeoJSON(monitoringPointsRef.current),
      });
      map.addLayer({
        id: "monitoring-circles",
        type: "circle",
        source: "monitoring",
        paint: {
          "circle-radius": 14,
          "circle-color": ["match", ["get", "type"],
            "air_quality", "#10b981", "traffic", "#f59e0b",
            "utilities", "#8b5cf6", "incident", "#ef4444", "#6b7280"],
          "circle-stroke-width": 3,
          "circle-stroke-color": "#ffffff",
          "circle-opacity": 0.55,
        },
      });

      // Complaint marker click → popup
      map.on("click", "complaint-circles", (e) => {
        const feature = e.features?.[0];
        if (!feature) return;
        const props = feature.properties as Record<string, string>;
        const coords = (feature.geometry as GeoJSON.Point).coordinates as [number, number];
        const color = PRIORITY_COLORS[props.priority] ?? "#6b7280";

        complaintsPopupRef.current?.remove();
        complaintsPopupRef.current = new mapboxgl.Popup({ offset: 12 })
          .setLngLat(coords)
          .setHTML(`
            <div style="font-family:system-ui,sans-serif;font-size:13px;max-width:220px">
              <div style="font-size:14px;font-weight:600;color:#111;margin-bottom:6px">${props.title}</div>
              <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px">
                <span style="background:${color}22;color:${color};border:1px solid ${color}55;padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600">
                  ${PRIORITY_LABELS[props.priority] ?? props.priority}
                </span>
                <span style="background:#f3f4f6;color:#374151;padding:2px 8px;border-radius:12px;font-size:11px">
                  ${STATUS_LABELS[props.status] ?? props.status}
                </span>
              </div>
              <a href="/complaints/${props.id}" style="font-size:11px;color:#2563eb;font-weight:500">Ətraflı bax →</a>
            </div>`)
          .addTo(map);
      });

      // Monitoring marker click → popup
      map.on("click", "monitoring-circles", (e) => {
        const feature = e.features?.[0];
        if (!feature) return;
        const props = feature.properties as Record<string, string>;
        const coords = (feature.geometry as GeoJSON.Point).coordinates as [number, number];

        new mapboxgl.Popup({ offset: 12 })
          .setLngLat(coords)
          .setHTML(`
            <div style="font-family:system-ui,sans-serif;font-size:13px;max-width:220px">
              <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.6px;margin-bottom:5px">${props.label}</div>
              <div style="color:#1a1a1a;line-height:1.4">${props.statusText}</div>
            </div>`)
          .addTo(map);
      });

      // Pointer cursor on hoverable layers
      ["complaint-circles", "monitoring-circles"].forEach((layer) => {
        map.on("mouseenter", layer, () => { map.getCanvas().style.cursor = "pointer"; });
        map.on("mouseleave", layer, () => {
          map.getCanvas().style.cursor = onLocationSelectRef.current ? "crosshair" : "";
        });
      });

      // ── Building selection ──────────────────────────────────────────────
      // GeoJSON source holds the currently selected building geometry
      map.addSource("selected-building", {
        type: "geojson",
        data: { type: "FeatureCollection", features: [] },
      });

      // Cyan glow highlight layer rendered on top of the normal buildings
      map.addLayer({
        id: "building-highlight",
        type: "fill-extrusion",
        source: "selected-building",
        paint: {
          "fill-extrusion-color": "#00d4ff",
          "fill-extrusion-height":  ["coalesce", ["get", "height"],     10],
          "fill-extrusion-base":    ["coalesce", ["get", "min_height"],  0],
          "fill-extrusion-opacity": 0.75,
        },
      });

      // Pointer cursor when hovering over a building
      map.on("mousemove", (e) => {
        const hit = map.queryRenderedFeatures(e.point, {
          layers: ["3d-buildings", "building-fill"].filter((id) => !!map.getLayer(id)),
        });
        map.getCanvas().style.cursor =
          hit.length > 0 ? "pointer"
          : onLocationSelectRef.current ? "crosshair"
          : "";
      });

      // ── Click: toggle building highlight + location pick ────────────────
      map.on("click", (e) => {
        const buildingLayers = ["3d-buildings", "building-fill"].filter(
          (id) => !!map.getLayer(id),
        );
        const buildings = map.queryRenderedFeatures(e.point, { layers: buildingLayers });

        if (buildings.length > 0) {
          const feat = buildings[0];
          // Use feature id, falling back to osm_id property for stable identity
          const fid: string | number | null =
            feat.id != null ? feat.id : (feat.properties?.osm_id ?? null);
          const fidStr = fid != null ? String(fid)
            : `${Math.round(e.lngLat.lat * 10000)}_${Math.round(e.lngLat.lng * 10000)}`;

          const src = map.getSource("selected-building") as mapboxgl.GeoJSONSource | undefined;

          if (fidStr === String(selectedBuildingIdRef.current ?? "")) {
            // Same building clicked → deselect
            selectedBuildingIdRef.current = null;
            src?.setData({ type: "FeatureCollection", features: [] });
            onBuildingClickRef.current?.(fidStr, e.lngLat.lat, e.lngLat.lng);
          } else {
            // New building clicked → highlight + notify parent
            selectedBuildingIdRef.current = fidStr;
            src?.setData({ type: "FeatureCollection", features: [feat as any] });
            onBuildingClickRef.current?.(fidStr, e.lngLat.lat, e.lngLat.lng);
          }
        }

        // Location pick (works regardless of whether a building was clicked)
        if (!onLocationSelectRef.current) return;
        const { lng, lat } = e.lngLat;
        onLocationSelectRef.current(lat, lng);
      });

      if (onLocationSelect) {
        map.getCanvas().style.cursor = "crosshair";
      }

      // Notify parent the map is fully loaded and ready to use
      onMapReady?.(map);
    });

    return () => {
      searchMarkerRef.current?.remove();
      searchPopupRef.current?.remove();
      selectedMarkerRef.current?.remove();
      complaintsPopupRef.current?.remove();
      map.remove();
      mapRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── Sync data sources after map loads ──────────────────────────────────
  useEffect(() => {
    const src = mapRef.current?.getSource("complaints") as mapboxgl.GeoJSONSource | undefined;
    src?.setData(buildComplaintsGeoJSON(complaints));
  }, [complaints]);

  useEffect(() => {
    const src = mapRef.current?.getSource("monitoring") as mapboxgl.GeoJSONSource | undefined;
    src?.setData(buildMonitoringGeoJSON(monitoringPoints));
  }, [monitoringPoints]);

  // ── Selected-location pin ───────────────────────────────────────────────
  useEffect(() => {
    if (!mapRef.current) return;
    selectedMarkerRef.current?.remove();
    selectedMarkerRef.current = null;
    if (selectedLocation) {
      selectedMarkerRef.current = new mapboxgl.Marker({ color: "#0078FF" })
        .setLngLat([selectedLocation.lng, selectedLocation.lat])
        .addTo(mapRef.current);
    }
  }, [selectedLocation]);

  // ── Search ──────────────────────────────────────────────────────────────
  const handleSearch = useCallback((value: string) => {
    setQuery(value);
    if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    if (!value.trim()) {
      setResults([]); setShowDropdown(false); setNoResults(false); return;
    }

    searchTimerRef.current = setTimeout(async () => {
      const centroid = districtCentroid.geometry.coordinates as [number, number];
      const [minLng, minLat, maxLng, maxLat] = districtBbox;
      const radiusMetres = Math.ceil(Math.max(maxLng - minLng, maxLat - minLat) * 111000);

      try {
        const url = new URL("https://catalog.api.2gis.com/3.0/items");
        url.searchParams.set("q", value);
        url.searchParams.set("point", `${centroid[0]},${centroid[1]}`);
        url.searchParams.set("radius", String(radiusMetres));
        url.searchParams.set("key", "303f450a-46b5-477e-b64a-f7772c635aff");
        url.searchParams.set("fields", "items.point,items.address");
        url.searchParams.set("lang", "az");
        url.searchParams.set("page_size", "30");

        const res = await fetch(url.toString());
        if (!res.ok) throw new Error();
        const json = await res.json();
        const items: any[] = json?.result?.items ?? [];

        const filtered: SearchResult[] = items
          .filter((i) => i.point)
          .filter((i) => turf.booleanPointInPolygon(
            turf.point([i.point.lon, i.point.lat]), districtSearch))
          .slice(0, 8)
          .map((i) => ({
            id: String(i.id),
            name: i.name ?? "",
            address: i.address_name ?? i.full_address_name ?? "",
            lon: i.point.lon,
            lat: i.point.lat,
          }));

        setResults(filtered);
        setNoResults(filtered.length === 0);
        setShowDropdown(true);
      } catch {
        setResults([]); setNoResults(false); setShowDropdown(false);
      }
    }, 300);
  }, []);

  const handleSelect = useCallback((result: SearchResult) => {
    if (!mapRef.current) return;
    searchMarkerRef.current?.remove();
    searchPopupRef.current?.remove();

    mapRef.current.flyTo({ center: [result.lon, result.lat], zoom: 16 });

    searchMarkerRef.current = new mapboxgl.Marker({ color: "#0078FF" })
      .setLngLat([result.lon, result.lat])
      .addTo(mapRef.current);

    searchPopupRef.current = new mapboxgl.Popup({ offset: 25 })
      .setLngLat([result.lon, result.lat])
      .setHTML(`<div style="font-family:system-ui,sans-serif;font-size:14px">
        <strong>${result.name}</strong>
        ${result.address ? `<br/><span style="color:#666;font-size:12px">${result.address}</span>` : ""}
      </div>`)
      .addTo(mapRef.current);

    onLocationSelectRef.current?.(result.lat, result.lon);
    setQuery(result.name);
    setShowDropdown(false);
    setResults([]);
  }, []);

  const handleClear = useCallback(() => {
    setQuery(""); setResults([]); setShowDropdown(false); setNoResults(false);
    searchMarkerRef.current?.remove(); searchMarkerRef.current = null;
    searchPopupRef.current?.remove(); searchPopupRef.current = null;
  }, []);

  const handleDistrictToggle = useCallback(() => {
    const map = mapRef.current;
    if (!map) return;

    setDistrictOnly((prev) => {
      const next = !prev;
      // Only change the outside shade opacity — base layers stay visible so
      // the district interior (buildings, roads) keeps rendering normally.
      map.setPaintProperty(
        "district-shade",
        "fill-color",
        next ? "rgba(0,0,0,1)" : "rgba(0,0,0,0.45)"
      );
      return next;
    });
  }, []);

  const handleGPS = useCallback(() => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      ({ coords }) => {
        const { longitude: lng, latitude: lat } = coords;
        if (mapRef.current) {
          mapRef.current.flyTo({ center: [lng, lat], zoom: 17 });
        }
        onLocationSelectRef.current?.(lat, lng);
      },
      () => alert("GPS məlumatı alınmadı. İcazə verin."),
      { enableHighAccuracy: true, timeout: 8000 }
    );
  }, []);

  // ── Render ──────────────────────────────────────────────────────────────
  if (!MAPBOX_TOKEN) {
    return (
      <div className="w-full h-full flex items-center justify-center bg-gray-100 text-sm text-gray-500 p-4 text-center">
        <p>Mapbox tokeni tapılmadı.<br />
          <code className="text-xs bg-gray-200 px-1 rounded">NEXT_PUBLIC_MAPBOX_TOKEN</code>ı
          {" "}<code className="text-xs bg-gray-200 px-1 rounded">.env.local</code> faylına əlavə edin.
        </p>
      </div>
    );
  }

  return (
    <div style={{ position: "relative", width: "100%", height: "100%" }}>
      {/* Search bar — hidden when parent provides its own UI */}
      {!hideBuiltinUI && <div style={{
        position: "absolute", top: 12, left: "50%", transform: "translateX(-50%)",
        zIndex: 10, width: "min(400px, calc(100% - 80px))",
        fontFamily: "system-ui,-apple-system,sans-serif",
      }}>
        <div style={{ position: "relative", display: "flex", alignItems: "center" }}>
          <input
            type="text"
            value={query}
            onChange={(e) => handleSearch(e.target.value)}
            onFocus={() => results.length > 0 && setShowDropdown(true)}
            placeholder="Nərimanov rayonunda axtar..."
            style={{
              width: "100%", padding: "10px 36px 10px 14px", borderRadius: 8,
              border: "1px solid rgba(0,0,0,0.15)", boxShadow: "0 2px 8px rgba(0,0,0,0.18)",
              fontSize: 14, outline: "none", background: "#fff", boxSizing: "border-box",
            }}
          />
          {query && (
            <button onClick={handleClear} aria-label="Clear" style={{
              position: "absolute", right: 10, background: "none", border: "none",
              cursor: "pointer", fontSize: 18, color: "#888", padding: 0, lineHeight: 1,
            }}>×</button>
          )}
        </div>

        {showDropdown && (results.length > 0 || noResults) && (
          <div style={{
            marginTop: 4, background: "#fff", borderRadius: 8,
            boxShadow: "0 4px 16px rgba(0,0,0,0.15)", overflow: "hidden",
            border: "1px solid rgba(0,0,0,0.08)",
          }}>
            {noResults ? (
              <div style={{ padding: "12px 14px", color: "#666", fontSize: 13 }}>
                Bu axtarış Nərimanov rayonu üçün nəticə vermədi
              </div>
            ) : results.map((r, i) => (
              <button key={r.id} onClick={() => handleSelect(r)} style={{
                display: "block", width: "100%", padding: "10px 14px", textAlign: "left",
                background: "none", border: "none",
                borderBottom: i < results.length - 1 ? "1px solid rgba(0,0,0,0.06)" : "none",
                cursor: "pointer", fontSize: 13,
              }}>
                <div style={{ fontWeight: 500, color: "#1a1a1a" }}>{r.name}</div>
                {r.address && <div style={{ color: "#888", fontSize: 12, marginTop: 2 }}>{r.address}</div>}
              </button>
            ))}
          </div>
        )}
      </div>}

      {/* Pick-mode hint + GPS button */}
      {!hideBuiltinUI && onLocationSelect && (
        <div style={{
          position: "absolute", bottom: 16, left: "50%", transform: "translateX(-50%)",
          zIndex: 10, display: "flex", alignItems: "center", gap: 8,
          fontFamily: "system-ui,-apple-system,sans-serif",
        }}>
          <div style={{
            background: "rgba(0,0,0,0.65)", color: "#fff", fontSize: 12,
            padding: "6px 14px", borderRadius: 20, pointerEvents: "none", whiteSpace: "nowrap",
          }}>
            Xəritədə problemi olan yerə klikləyin
          </div>
          <button onClick={handleGPS} title="GPS ilə cari yeri seç" style={{
            background: "#fff", border: "none", borderRadius: "50%",
            width: 36, height: 36, display: "flex", alignItems: "center",
            justifyContent: "center", cursor: "pointer",
            boxShadow: "0 2px 8px rgba(0,0,0,0.25)", flexShrink: 0,
          }}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"
              stroke="#0078FF" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="3" />
              <path d="M12 2v3M12 19v3M2 12h3M19 12h3" />
              <circle cx="12" cy="12" r="8" strokeDasharray="2 4" />
            </svg>
          </button>
        </div>
      )}

      {/* District-only toggle button — hidden when parent provides its own */}
      {!hideBuiltinUI && <div style={{
        position: "absolute", bottom: 16, left: 16, zIndex: 10,
        fontFamily: "system-ui,-apple-system,sans-serif",
      }}>
        <button
          onClick={handleDistrictToggle}
          title={districtOnly ? "Normal xəritəyə qayıt" : "Yalnız Nərimanov rayonunu göstər"}
          style={{
            display: "flex", alignItems: "center", gap: 8,
            padding: "8px 14px", borderRadius: 8, border: "none",
            cursor: "pointer", fontSize: 12, fontWeight: 600,
            boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
            background: districtOnly ? "#003DA5" : "#fff",
            color: districtOnly ? "#fff" : "#1a1a1a",
            transition: "background 0.2s, color 0.2s",
          }}
        >
          {/* Map layers icon */}
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none"
            stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="12 2 2 7 12 12 22 7 12 2" />
            <polyline points="2 17 12 22 22 17" />
            <polyline points="2 12 12 17 22 12" />
          </svg>
          {districtOnly ? "Tam Xəritə" : "Rayon Rejimi"}
        </button>
      </div>}

      {/* Hide Mapbox logo + attribution */}
      <style>{`.mapboxgl-ctrl-logo,.mapboxgl-ctrl-attrib{display:none!important}`}</style>

      {/* Map container */}
      <div ref={containerRef} style={{ width: "100%", height: "100%" }} />
    </div>
  );
}
